import base64
import hashlib
import os
import secrets
import time
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Any, Dict, Optional
from urllib.parse import parse_qs, urlencode, urlparse

import requests


class Auth0PKCELogin:
    AUTH_BASE = "https://{domain}/authorize"
    TOKEN_URL = "https://{domain}/oauth/token"

    def __init__(
        self,
        domain: str,
        client_id: str,
        redirect_uri: str,
        audience: Optional[str] = None,
        scope: str = "openid profile email offline_access",
        session: Optional[requests.Session] = None,
    ) -> None:
        self.domain = domain
        self.client_id = client_id
        self.redirect_uri = redirect_uri
        self.audience = audience
        self.scope = scope
        self.session = session or requests.Session()

    @staticmethod
    def _b64url(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

    @classmethod
    def generate_code_verifier(cls, length: int = 64) -> str:
        if not 43 <= length <= 128:
            raise ValueError("PKCE code_verifier length must be between 43 and 128")
        raw = cls._b64url(secrets.token_bytes(length))
        if len(raw) < 43:
            raw += "A" * (43 - len(raw))
        return raw[: min(len(raw), 128)]

    @classmethod
    def generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._b64url(digest)

    @staticmethod
    def generate_state() -> str:
        return secrets.token_urlsafe(32)

    def build_authorization_url(
        self,
        code_challenge: str,
        state: str,
        extra_params: Optional[Dict[str, str]] = None,
    ) -> str:
        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
            "state": state,
        }
        if self.audience:
            params["audience"] = self.audience
        if extra_params:
            params.update(extra_params)
        return self.AUTH_BASE.format(domain=self.domain) + "?" + urlencode(params)

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict[str, Any]:
        url = self.TOKEN_URL.format(domain=self.domain)
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        response = self.session.post(
            url,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def refresh_tokens(self, refresh_token: str) -> Dict[str, Any]:
        url = self.TOKEN_URL.format(domain=self.domain)
        payload = {
            "grant_type": "refresh_token",
            "client_id": self.client_id,
            "refresh_token": refresh_token,
        }
        response = self.session.post(
            url,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def login_via_browser(
        self,
        open_browser: bool = True,
        timeout: int = 300,
        success_html: str = "<html><body><h1>Login complete</h1>You may close this window.</body></html>",
        error_html: str = "<html><body><h1>Login failed</h1>You may close this window.</body></html>",
    ) -> Dict[str, Any]:
        parsed = urlparse(self.redirect_uri)
        if parsed.scheme != "http" or not parsed.hostname or not parsed.port:
            raise ValueError("redirect_uri must be an http:// URL with an explicit host and port for local callback handling")

        code_verifier = self.generate_code_verifier()
        code_challenge = self.generate_code_challenge(code_verifier)
        expected_state = self.generate_state()
        auth_url = self.build_authorization_url(code_challenge=code_challenge, state=expected_state)

        result: Dict[str, Any] = {"code": None, "state": None, "error": None, "error_description": None}

        class CallbackHandler(BaseHTTPRequestHandler):
            def do_GET(self) -> None:
                qs = parse_qs(urlparse(self.path).query)
                result["code"] = qs.get("code", [None])[0]
                result["state"] = qs.get("state", [None])[0]
                result["error"] = qs.get("error", [None])[0]
                result["error_description"] = qs.get("error_description", [None])[0]

                if result["code"] and result["state"] == expected_state and not result["error"]:
                    body = success_html.encode("utf-8")
                    self.send_response(200)
                else:
                    body = error_html.encode("utf-8")
                    self.send_response(400)

                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def log_message(self, format: str, *args: Any) -> None:
                return

        server = HTTPServer((parsed.hostname, parsed.port), CallbackHandler)
        server.timeout = 1

        if open_browser:
            webbrowser.open(auth_url, new=1, autoraise=True)

        start = time.time()
        while time.time() - start < timeout:
            server.handle_request()
            if result["code"] or result["error"]:
                break

        server.server_close()

        if result["error"]:
            raise RuntimeError(f"Authorization failed: {result['error']} ({result['error_description']})")

        if result["state"] != expected_state:
            raise RuntimeError("State mismatch in OAuth callback")

        if not result["code"]:
            raise TimeoutError("Timed out waiting for OAuth authorization response")

        tokens = self.exchange_code_for_tokens(result["code"], code_verifier)
        tokens["provider"] = "auth0"
        tokens["authorization_url"] = auth_url
        return tokens


def build_auth0_client_from_env() -> Auth0PKCELogin:
    domain = os.environ["AUTH0_DOMAIN"]
    client_id = os.environ["AUTH0_CLIENT_ID"]
    redirect_uri = os.environ["AUTH0_REDIRECT_URI"]
    audience = os.environ.get("AUTH0_AUDIENCE")
    scope = os.environ.get("AUTH0_SCOPE", "openid profile email offline_access")
    return Auth0PKCELogin(
        domain=domain,
        client_id=client_id,
        redirect_uri=redirect_uri,
        audience=audience,
        scope=scope,
    )
